  "art": "desktop sheet",
  "thumb": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"59\" height=\"55.5\" viewBox=\"0 0 118 111\"><image href=\"data:image/png;base64,\" width=\"944\" height=\"111\" image-rendering=\"pixelated\" style=\"image-rendering:pixelated\"><animate attributeName=\"x\" values=\"0;-118;-236;-354;-472;-590;-708;-826\" keyTimes=\"0;0.125;0.25;0.375;0.5;0.625;0.75;0.875\" calcMode=\"discrete\" dur=\"1.333s\" repeatCount=\"indefinite\"/></image></svg>",
